// Parse ISO 8601 UTC date strings used on invoices.
export function parseInvoiceDate(value: string): Date {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    throw new Error(`invalid invoice date: ${value}`);
  }
  return d;
}

// Format a Date as an ISO 8601 UTC string.
export function formatInvoiceDate(d: Date): string {
  return d.toISOString();
}

