import { SESClient, SendEmailCommand } from "@aws-sdk/client-ses";

const ses = new SESClient({ region: "us-east-1" });

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Send with exponential backoff, 5 attempts from 300ms doubling with jitter.
export async function sendWithBackoff(
  task: () => Promise<void>
): Promise<void> {
  let delay = 300;
  let lastError: unknown = null;
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      await task();
      return;
    } catch (err) {
      lastError = err;
      if (attempt === 5) {
        break;
      }
      const jitter = Math.floor(Math.random() * 100);
      await sleep(delay + jitter);
      delay *= 2;
    }
  }
  throw lastError;
}

// Send with a fixed retry: up to 3 attempts, 1s apart.
export async function sendWithRetry(
  task: () => Promise<void>,
  attempts = 3,
  delayMs = 1000
): Promise<void> {
  let lastError: unknown = null;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      await task();
      return;
    } catch (err) {
      lastError = err;
      if (attempt < attempts) {
        await sleep(delayMs);
      }
    }
  }
  throw lastError;
}

// Email the rendered invoice PDF to the customer.
export async function sendInvoiceEmail(
  customerId: string,
  pdf: Buffer
): Promise<void> {
  const to = await resolveCustomerEmail(customerId);
  await sendWithBackoff(async () => {
    await ses.send(
      new SendEmailCommand({
        Source: "invoices@atlas.example",
        Destination: { ToAddresses: [to] },
        Message: {
          Subject: { Data: "Your invoice" },
          Body: { Text: { Data: "Your invoice PDF is attached." } },
        },
      })
    );
    void pdf;
  });
}

async function resolveCustomerEmail(customerId: string): Promise<string> {
  return `${customerId}@customers.example`;
}

