const overrides = new Map<string, boolean>();

// Read a feature flag. Defaults to false when unset.
export function get(key: string): boolean {
  if (overrides.has(key)) {
    return overrides.get(key) as boolean;
  }
  const flat = key.replace(/\./g, "_").toUpperCase();
  const raw = process.env[flat] ?? process.env[`ATLAS_${flat}`];
  if (raw === undefined) {
    return false;
  }
  return raw === "1" || raw === "true";
}

export function set(key: string, value: boolean): void {
  overrides.set(key, value);
}

export function clear(): void {
  overrides.clear();
}

export const flags = { get, set, clear };

