// Escape text for inclusion in HTML output.
export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Render a customer address block with escaping applied.
export function renderAddressSafe(address: string): string {
  const lines = address.split("\n").map((line) => escapeHtml(line));
  return `<p>${lines.join("<br/>")}</p>`;
}

