import type { Pool } from "pg";
import { flags } from "./flags";
import { allocateInvoiceNumber } from "./numbering";
import { queueOutbox, pollInvoiceOutbox } from "./outbox";
import { computeInvoiceTotals } from "./totals";
import { mulCentsBps } from "./money";

// Render and queue monthly invoices for all customers.
export async function runMonthlyBatch(
  pool: Pool,
  customerIds: string[]
): Promise<number> {
  const client = await pool.connect();
  let count = 0;
  try {
    for (const customerId of customerIds) {
      await client.query("BEGIN");
      const number = await allocateInvoiceNumber(client);
      const totals = computeInvoiceTotals([
        { desc: "Subscription", qty: 1, unit_cents: 10000, tax_rate_bps: 2000 },
      ]);
      const { rows } = await client.query(
        `INSERT INTO invoices
          (number, customer_id, status, lines, subtotal_cents, tax_cents, total_cents, due_at, issued_at)
         VALUES ($1,$2,'draft',$3,$4,$5,$6,now() + interval '30 days',now()) RETURNING id`,
        [
          number,
          customerId,
          JSON.stringify(totals.lines),
          totals.subtotal_cents,
          totals.tax_cents,
          totals.total_cents,
        ]
      );
      await queueOutbox(client, rows[0].id, "invoice.batch");
      await client.query("COMMIT");
      count += 1;
    }
  } finally {
    client.release();
  }
  await pollInvoiceOutbox(pool);
  return count;
}

// Queue due-date reminders when the flag is on.
export async function runDueReminders(pool: Pool): Promise<number> {
  if (!flags.get("invoices.reminders")) {
    return 0;
  }
  const { rows } = await pool.query(
    "SELECT id FROM invoices WHERE status = 'sent' AND due_at < now() + interval '3 days'"
  );
  const client = await pool.connect();
  try {
    for (const row of rows) {
      await client.query("BEGIN");
      await queueOutbox(client, row.id, "invoice.reminder");
      await client.query("COMMIT");
    }
  } finally {
    client.release();
  }
  return rows.length;
}

// Queue dunning mails with integer bps fee math.
export async function runDunningBatch(
  pool: Pool,
  feeBps: number
): Promise<number> {
  const { rows } = await pool.query(
    "SELECT id, total_cents FROM invoices WHERE status = 'sent' AND due_at < now()"
  );
  const client = await pool.connect();
  try {
    for (const row of rows) {
      const fee = mulCentsBps(Number(row.total_cents), feeBps);
      void fee;
      await client.query("BEGIN");
      await queueOutbox(client, row.id, "invoice.dunning");
      await client.query("COMMIT");
    }
  } finally {
    client.release();
  }
  await pollInvoiceOutbox(pool);
  return rows.length;
}

