// Integer cents arithmetic for money fields.
export function addCents(a: number, b: number): number {
  assertCents(a);
  assertCents(b);
  return a + b;
}

// Multiply cents by a basis-point rate, half-up to a cent.
export function mulCentsBps(cents: number, bps: number): number {
  assertCents(cents);
  assertBps(bps);
  return Math.floor((cents * bps + 5000) / 10000);
}

function assertCents(n: number): void {
  if (!Number.isInteger(n)) {
    throw new Error(`expected integer cents, got ${n}`);
  }
}

function assertBps(n: number): void {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error(`expected integer bps, got ${n}`);
  }
}

