import type { PoolClient } from "pg";

// Allocate the next invoice number for the invoice month.
export async function allocateInvoiceNumber(
  client: PoolClient,
  now: Date = new Date()
): Promise<string> {
  const year = now.getUTCFullYear();
  const month = String(now.getUTCMonth() + 1).padStart(2, "0");
  const { rows } = await client.query(
    "SELECT nextval('invoices_seq') AS seq"
  );
  const seq = Number(rows[0].seq);
  const padded = String(seq).padStart(5, "0");
  return `ATL-${year}${month}-${padded}`;
}

// Allocate the next credit-note number from its own sequence.
export async function allocateCreditNoteNumber(
  client: PoolClient
): Promise<string> {
  const { rows } = await client.query(
    "SELECT nextval('credit_notes_seq') AS seq"
  );
  const seq = Number(rows[0].seq);
  return `CN-${String(seq).padStart(6, "0")}`;
}

// Format a yearly invoice number.
export function formatYearlyInvoiceNumber(year: number, seq: number): string {
  return `INV-${year}-${String(seq).padStart(4, "0")}`;
}

// Validate stored invoice and credit-note numbers.
export function isInvoiceNumber(value: string): boolean {
  return (
    /^ATL-\d{6}-\d{5}$/.test(value) ||
    /^INV-\d{4}-\d{4}$/.test(value) ||
    /^CN-\d{6}$/.test(value)
  );
}

