import type { Pool, PoolClient } from "pg";
import { sendInvoiceEmail } from "./email";
import { renderInvoicePdfAsync } from "./render";

// Write an outbox row inside the current transaction.
export async function queueOutbox(
  client: PoolClient,
  invoiceId: string,
  kind: string
): Promise<void> {
  await client.query(
    "INSERT INTO invoice_outbox (invoice_id, kind, created_at) VALUES ($1, $2, now())",
    [invoiceId, kind]
  );
}

// Send pending outbox rows after their transactions commit.
export async function pollInvoiceOutbox(pool: Pool): Promise<number> {
  const { rows } = await pool.query(
    "SELECT id, invoice_id, kind FROM invoice_outbox WHERE sent_at IS NULL ORDER BY created_at LIMIT 50"
  );
  let sent = 0;
  for (const row of rows) {
    const inv = await pool.query("SELECT * FROM invoices WHERE id = $1", [
      row.invoice_id,
    ]);
    if (inv.rows.length === 0) {
      continue;
    }
    const pdf = await renderInvoicePdfAsync(inv.rows[0]);
    await sendInvoiceEmail(inv.rows[0].customer_id, pdf);
    await pool.query("UPDATE invoice_outbox SET sent_at = now() WHERE id = $1", [
      row.id,
    ]);
    sent += 1;
  }
  return sent;
}

