import fs from "fs";
import path from "path";
import { PDFDocument, StandardFonts } from "pdf-lib";
import { escapeHtml, renderAddressSafe } from "./html";

export interface RenderInvoice {
  number: string;
  status: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_at: string;
  customer_address?: string;
  lines: Array<{
    desc: string;
    qty: number;
    unit_cents: number;
    tax_cents: number;
  }>;
}

// Render the invoice PDF with the vector template.
export async function renderInvoicePdfAsync(
  invoice: RenderInvoice
): Promise<Buffer> {
  const templatePath = path.join(
    __dirname,
    "..",
    "..",
    "invoices",
    "templates",
    "vector.hbs"
  );
  const template = fs.readFileSync(templatePath, "utf8");
  const address = renderAddressSafe(invoice.customer_address ?? "");
  const body = template
    .replace("{{number}}", escapeHtml(invoice.number))
    .replace("{{status}}", escapeHtml(invoice.status))
    .replace("{{address}}", address)
    .replace("{{total_cents}}", String(invoice.total_cents));

  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const page = doc.addPage([595, 842]);
  page.drawText(stripTags(body).slice(0, 4000), {
    x: 48,
    y: 780,
    size: 10,
    font,
  });
  const bytes = await doc.save();
  return Buffer.from(bytes);
}

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, " ");
}

