import { Router } from "express";
import { getPool } from "./store";
import { createInvoice, sendInvoice, createCreditNote } from "./service";

export function invoicesRouter(): Router {
  const router = Router();

  router.post("/invoices", async (req, res) => {
    try {
      const pool = getPool();
      const invoice = await createInvoice(pool, req.body);
      res.status(201).json(invoice);
    } catch (err) {
      res.status(400).json({ error: String(err) });
    }
  });

  router.get("/invoices", async (req, res) => {
    const offset = Number(req.query.offset ?? 0);
    const limit = Number(req.query.limit ?? 20);
    const pool = getPool();
    const { rows } = await pool.query(
      "SELECT * FROM invoices ORDER BY issued_at DESC OFFSET $1 LIMIT $2",
      [offset, limit]
    );
    res.json({ invoices: rows, offset, limit });
  });

  router.get("/invoices/:id", async (req, res) => {
    const pool = getPool();
    const { rows } = await pool.query("SELECT * FROM invoices WHERE id = $1", [
      req.params.id,
    ]);
    if (rows.length === 0) {
      res.status(404).json({ error: "not found" });
      return;
    }
    const cn = await pool.query(
      "SELECT * FROM credit_notes WHERE invoice_id = $1",
      [req.params.id]
    );
    res.json({ ...rows[0], credit_notes: cn.rows });
  });

  router.post("/invoices/:id/send", async (req, res) => {
    try {
      const pool = getPool();
      const invoice = await sendInvoice(pool, req.params.id);
      res.json(invoice);
    } catch (err) {
      res.status(400).json({ error: String(err) });
    }
  });

  router.post("/invoices/:id/credit-notes", async (req, res) => {
    try {
      const pool = getPool();
      const note = await createCreditNote(
        pool,
        req.params.id,
        req.body.amount_cents,
        req.body.reason
      );
      res.status(201).json(note);
    } catch (err) {
      res.status(400).json({ error: String(err) });
    }
  });

  return router;
}

