import type { Pool, PoolClient } from "pg";
import { addCents, mulCentsBps } from "./money";
import { parseInvoiceDate, formatInvoiceDate } from "./dates";
import { allocateInvoiceNumber, allocateCreditNoteNumber } from "./numbering";
import { computeInvoiceTotals, InvoiceLineInput } from "./totals";
import { queueOutbox } from "./outbox";
import { InvoiceStatus, setInvoiceStatus } from "./status";

export interface CreateInvoiceInput {
  customerId: string;
  lines: InvoiceLineInput[];
  due_at: string;
}

// Create an invoice and queue its send mail in the same transaction.
export async function createInvoice(
  pool: Pool,
  input: CreateInvoiceInput
): Promise<Record<string, unknown>> {
  const due = parseInvoiceDate(input.due_at);
  const totals = computeInvoiceTotals(input.lines);
  const client: PoolClient = await pool.connect();
  try {
    await client.query("BEGIN");
    const number = await allocateInvoiceNumber(client);
    const issued = formatInvoiceDate(new Date());
    const { rows } = await client.query(
      `INSERT INTO invoices
        (number, customer_id, status, lines, subtotal_cents, tax_cents, total_cents, due_at, issued_at)
       VALUES ($1,$2,'draft',$3,$4,$5,$6,$7,$8) RETURNING *`,
      [
        number,
        input.customerId,
        JSON.stringify(totals.lines),
        totals.subtotal_cents,
        totals.tax_cents,
        totals.total_cents,
        due.toISOString(),
        issued,
      ]
    );
    await queueOutbox(client, rows[0].id, "invoice.created");
    await client.query("COMMIT");
    return toApi(rows[0]);
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

// Transition draft to sent and queue the send mail.
export async function sendInvoice(
  pool: Pool,
  id: string
): Promise<Record<string, unknown>> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const { rows } = await client.query(
      "SELECT * FROM invoices WHERE id = $1 FOR UPDATE",
      [id]
    );
    if (rows.length === 0) {
      throw new Error("invoice not found");
    }
    const next: InvoiceStatus = setInvoiceStatus(rows[0].status, "sent");
    const updated = await client.query(
      "UPDATE invoices SET status = $1 WHERE id = $2 RETURNING *",
      [next, id]
    );
    await queueOutbox(client, id, "invoice.send");
    await client.query("COMMIT");
    return toApi(updated.rows[0]);
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

// Create a credit note against a sent or paid invoice.
export async function createCreditNote(
  pool: Pool,
  id: string,
  amountCents: number,
  reason: string
): Promise<Record<string, unknown>> {
  if (!Number.isInteger(amountCents) || amountCents <= 0) {
    throw new Error("amount_cents is integer cents");
  }
  const prorated = mulCentsBps(amountCents, 10000);
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const { rows } = await client.query(
      "SELECT * FROM invoices WHERE id = $1 FOR UPDATE",
      [id]
    );
    if (rows.length === 0) {
      throw new Error("invoice not found");
    }
    const current = rows[0].status as InvoiceStatus;
    const next = setInvoiceStatus(current, "credited");
    const cnNumber = await allocateCreditNoteNumber(client);
    await client.query(
      `INSERT INTO credit_notes (number, invoice_id, amount_cents, reason, created_at)
       VALUES ($1,$2,$3,$4,now())`,
      [cnNumber, id, addCents(0, prorated), reason]
    );
    const updated = await client.query(
      "UPDATE invoices SET status = $1 WHERE id = $2 RETURNING *",
      [next, id]
    );
    await queueOutbox(client, id, "invoice.credit");
    await client.query("COMMIT");
    const api = toApi(updated.rows[0]);
    (api as Record<string, unknown>)["credit_note_number"] = cnNumber;
    return api;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

export function toApi(row: Record<string, unknown>): Record<string, unknown> {
  return {
    id: row["id"],
    number: row["number"],
    status: row["status"],
    lines: row["lines"],
    subtotal_cents: row["subtotal_cents"],
    tax_cents: row["tax_cents"],
    total_cents: row["total_cents"],
    due_at: row["due_at"],
  };
}

