export type InvoiceStatus = "draft" | "sent" | "paid" | "credited";

export class IllegalTransitionError extends Error {
  constructor(from: InvoiceStatus, to: InvoiceStatus) {
    super(`illegal status transition ${from} to ${to}`);
    this.name = "IllegalTransitionError";
  }
}

// Edges allowed between invoice statuses.
export const allowedInvoiceTransitions: Record<InvoiceStatus, InvoiceStatus[]> = {
  draft: ["sent"],
  sent: ["paid", "credited"],
  paid: ["credited"],
  credited: [],
};

// Move an invoice status along an allowed edge.
export function setInvoiceStatus(
  current: InvoiceStatus,
  next: InvoiceStatus
): InvoiceStatus {
  const allowed = allowedInvoiceTransitions[current] ?? [];
  if (!allowed.includes(next)) {
    throw new IllegalTransitionError(current, next);
  }
  return next;
}

