// Half-up tax rounding on a cents total for a bps rate.
export function roundTaxCents(totalCents: number, rateBps: number): number {
  if (!Number.isInteger(totalCents) || !Number.isInteger(rateBps)) {
    throw new Error("expected integer cents and bps");
  }
  if (totalCents < 0 || rateBps < 0) {
    throw new Error("expected non-negative inputs");
  }
  return Math.floor((totalCents * rateBps + 5000) / 10000);
}

