import { addCents } from "./money";
import { roundTaxCents } from "./tax";

export interface InvoiceLineInput {
  desc: string;
  qty: number;
  unit_cents: number;
  tax_rate_bps: number;
}

export interface InvoiceLineComputed extends InvoiceLineInput {
  line_total_cents: number;
  tax_cents: number;
}

export interface InvoiceTotals {
  lines: InvoiceLineComputed[];
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
}

// Compute line totals, subtotal, tax and total in integer cents.
export function computeInvoiceTotals(lines: InvoiceLineInput[]): InvoiceTotals {
  let subtotal = 0;
  const computed: InvoiceLineComputed[] = lines.map((line) => {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      throw new Error("qty is a positive integer");
    }
    if (!Number.isInteger(line.unit_cents) || line.unit_cents < 0) {
      throw new Error("unit_cents is integer cents");
    }
    let lineTotal = 0;
    for (let i = 0; i < line.qty; i++) {
      lineTotal = addCents(lineTotal, line.unit_cents);
    }
    subtotal = addCents(subtotal, lineTotal);
    return {
      ...line,
      line_total_cents: lineTotal,
      tax_cents: roundTaxCents(lineTotal, line.tax_rate_bps),
    };
  });

  const rates = new Set(computed.map((l) => l.tax_rate_bps));
  let tax: number;
  if (rates.size === 1 && computed.length > 0) {
    tax = roundTaxCents(subtotal, computed[0].tax_rate_bps);
  } else {
    tax = 0;
    for (const line of computed) {
      tax = addCents(tax, line.tax_cents);
    }
  }
  const total = addCents(subtotal, tax);
  return { lines: computed, subtotal_cents: subtotal, tax_cents: tax, total_cents: total };
}

