import {
  setInvoiceStatus,
  allowedInvoiceTransitions,
} from "../../src/invoices/status";

describe("InvoiceStatus", () => {
  test("allows draft to sent", () => {
    expect(setInvoiceStatus("draft", "sent")).toBe("sent");
  });

  test("rejects illegal credit-note transition", () => {
    expect(allowedInvoiceTransitions["paid"]).toContain("credited");
    expect(() => setInvoiceStatus("paid", "draft")).toThrow();
  });

  test("credited is terminal", () => {
    expect(allowedInvoiceTransitions["credited"]).toEqual([]);
    expect(() => setInvoiceStatus("credited", "sent")).toThrow();
  });
