      { desc: "service", qty: 2, unit_cents: 1000, tax_rate_bps: 2000 },
    ]);
    expect(totals.subtotal_cents).toBe(2000);
    expect(totals.tax_cents).toBe(400);
    expect(totals.total_cents).toBe(2400);
    expect(totals.lines[0].tax_cents).toBe(400);
  });

  test("keeps per-line tax breakdown on lines", () => {
    const totals = computeInvoiceTotals([
      { desc: "x", qty: 1, unit_cents: 333, tax_rate_bps: 1000 },
    ]);
    expect(totals.lines[0].tax_cents).toBe(33);
  });
});
